  values ('hangzhou-style-noodles', 'Hangzhou-Style Noodles', 'Hangzhou-Style Noodles', 'hangzhou', 'hangzhou-other', 'food', 'Try Fang Lao Da (Michelin Bib Gourmand) for authentic Hangzhou noodles. Or explore Wulin Night Market for street food variety. Pian''er Chuan (sliced pork noodles with bamboo shoots) is a local favorite.', 'Noodles', null, null, null, null, null, 'classic-hangzhou-guide.html', 'CN')
