  values ('qiandao-lake', 'Qiandao Lake', 'Qiandao Lake', 'hangzhou', 'hangzhou-other', 'sight', 'Thousand Island Lake — massive man-made reservoir with 1,078 islands. Crystal clear water, scenic cruises, island hopping, and outdoor activities. About 2 hours by high-speed train or bus.', 'Scenic', null, null, null, null, null, 'classic-hangzhou-guide.html', 'CN')
