  values ('wuzhen-xitang', 'Wuzhen / Xitang', 'Wuzhen / Xitang', 'hangzhou', 'hangzhou-other', 'sight', 'Classic Jiangnan water towns with stone bridges, canals, and whitewashed houses. Wuzhen is beautifully restored (more touristy but stunning); Xitang is more atmospheric and authentic. Both ~1 hour by train.', 'Water Town', null, null, null, null, null, 'classic-hangzhou-guide.html', 'CN')
