  values ('hallucination-immersive-theatre', '幻觉沉浸式剧场', 'Hallucination Immersive Theatre', 'hangzhou', 'gongshu', 'activity', 'Southeast Asian-themed horror "Road to the Underworld: Gluttony." Spacious scenes with cinema-level sound and light effects, outstanding NPC acting, intense chase sequences, and clever mechanisms. Even has wheelchair-accessible spots!', 'Immersive Theatre, Immersive Horror, Horror, Live NPCs', null, null, 'Xintiandi, Gongshu District', null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('songcheng-romance-show', '宋城 · 千古情', 'Songcheng Romance Show', 'hangzhou', 'hangzhou-other', 'activity', 'Songcheng theme park with "The Romantic Show of Songcheng" — hailed as one of the "World''s Top 3 Must-See Shows" alongside Las Vegas'' "O" and Paris'' Moulin Rouge. Epic sound, lighting, and stage mechanics bring ancient Liangzhu to life.', 'Show, World-Class Show', null, null, null, null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
