  values ('impression-west-lake', '印象西湖 · 最忆是杭州', 'Impression West Lake', 'hangzhou', 'xihu', 'activity', '"Enduring Memories of Hangzhou" — open-air spectacle directed by Zhang Yimou (2008 Olympics ceremony director). Stage is submerged in West Lake itself. Dance, opera, and music against the lake backdrop. Book 3+ days in advance.', 'Show, Water Spectacle', null, null, null, null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('chuiyun-underground-river', '垂云通天河', 'Chuiyun Underground River', 'hangzhou', 'hangzhou-other', 'activity', 'In Tonglu — vertical underground river with crystal clear water and natural stalactites. Features NPC interactions,地心探险 (Earth''s Core Adventure) with water guns through stone caves, plus glass skywalk and mountain karting.', 'Nature Adventure', null, null, 'Tonglu County · 1.5hr from Hangzhou', null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('hongboyuan-outdoor-camp', '红博苑户外营地', 'Hongboyuan Outdoor Camp', 'hangzhou', 'xiaoshan', 'activity', 'Xiaoshan outdoor complex with 6 activities: karting, BBQ camping, paintball/CQB, kayaking, archery, and fruit/vegetable picking. Perfect for large groups, team building, or a full day of outdoor fun.', 'Multi-Activity', null, null, 'Xiaoshan District', null, null, 'hangzhou-fun-guide.html', 'CN')
