insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('grand-canal-water-bus', 'Grand Canal Water Bus', 'Grand Canal Water Bus', 'hangzhou', 'gongshu', 'activity', 'Ride the public water bus from Wulin Gate to Gongchen Bridge for only ~¥3! A unique perspective on Hangzhou''s residential life along the UNESCO World Heritage Grand Canal. Explore Xiaohezhi Street and canal museums at the end.', 'Transport, Canal Cruise', null, null, null, null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('xiaohe-straight-street', '小河直街', 'Xiaohe Straight Street', 'hangzhou', 'gongshu', 'activity', 'Hangzhou''s own old quarter on the Grand Canal, and the one that never got scrubbed into a souvenir street. Whitewashed walls, black tile roofs, people still living in them, and a row of canal-side coffee roasters, craft studios and teahouses. The local pick for a slow afternoon walk and the best Jiangnan photographs in the city.', 'Old Street, MUST GO, Canal, Coffee and Teahouses, Citywalk', 0, 0, 'Xiaohe Straight Street, Gongshu District, on the Grand Canal', null, 120, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('qiaoxi-historic-block', '桥西历史街区', 'Qiaoxi Historic Block', 'hangzhou', 'gongshu', 'activity', 'The other bank of the Gongchen Bridge, five minutes from Xiaohe Straight Street: restored Qing warehouses now holding the Umbrella, Fan and Knife and Sword museums, and the street food stalls locals queue at. Pair the two in one walk rather than making a separate trip.', 'Old Street, WORTH A DETOUR, Canal, Museums, Street Food', 0, 0, 'Qiaoxi, Gongchen Bridge, Grand Canal, Gongshu District', null, 120, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('nine-creeks-and-eighteen-gullies', '九溪十八涧', 'Nine Creeks and Eighteen Gullies', 'hangzhou', 'xihu', 'activity', 'The walk everyone in Hangzhou does and almost no visitor finds: a Y-shaped valley of small streams running down through tea terraces and forest to the Qiantang River. Cool in summer, red leaves in late autumn, and mist through the trees the morning after rain. Flat, shaded, and about 5km end to end.', 'Hike, MUST GO, Walk, Tea Terraces, Free', 0, 0, 'West Lake scenic area, Xihu District, below Longjing', null, 180, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('yunqi-bamboo-path', '云栖竹径', 'Yunqi Bamboo Path', 'hangzhou', 'xihu', 'activity', 'A stone path through a dense bamboo grove on the far side of the hills, several degrees cooler than the lake and almost silent on a weekday. Small, quick, and the obvious pairing with Nine Creeks or Meijiawu since all three sit on the same road.', 'Hike, WORTH A DETOUR, Bamboo, Quiet, Summer Escape', 8, 8, 'Yunqi Road, West Lake scenic area, Xihu District', null, 60, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('liangzhu-ancient-city-ruins-park', '良渚古城遗址公园', 'Liangzhu Ancient City Ruins Park', 'hangzhou', 'hangzhou-other', 'activity', 'UNESCO World Heritage and the source of 5,000-year-old Liangzhu civilisation, on a site big enough to need its own shuttle. Mojiaoshan palace mound, the Fanshan royal tombs, a deer park you can feed, and the jade in the Liangzhu Museum nearby. Free, but book the entry slot ahead online.', 'Heritage Site, MUST GO, UNESCO, Free Booking, Half Day', 0, 0, 'Yuhang, north-west of the city, about 40 minutes out on Metro Line 2', null, null, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('deshou-palace-museum', '南宋德寿宫遗址博物馆', 'Deshou Palace Museum', 'hangzhou', 'shangcheng', 'activity', 'The Southern Song imperial palace excavated in place and roofed over, with the foundations left exactly as dug and the hall rebuilt in projection above them. The best single hour on why Hangzhou was once the capital of China. Free, timed entry, and closed Mondays.', 'Museum, MUST GO, Southern Song, Indoor, Rainy Day', 0, 0, 'Wangjiang Road near Qingtai Street, Shangcheng District', null, 120, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('liuhe-pagoda', '六和塔', 'Liuhe Pagoda', 'hangzhou', 'xihu', 'activity', 'A 970 AD pagoda built to calm the Qiantang tidal bore, thirteen exterior storeys up the hillside with the river and the bridge laid out below. Worth climbing if you are already heading out this way, not worth a special trip in from the lake.', 'Heritage Site, WORTH A DETOUR, Pagoda, River View, Climb', 20, 20, 'Zhijiang Road, West Lake District, above the Qiantang River', null, 60, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('taiziwan-park', '太子湾公园', 'Taiziwan Park', 'hangzhou', 'xihu', 'activity', 'The lakeside park that goes viral every spring for cherry blossom and tulips, and is an ordinary pleasant park the rest of the year. Come in the March to April flowering window or skip it: at peak bloom it is shoulder to shoulder, and out of season there is nothing here the lake shore does not already give you.', 'Park, WORTH A DETOUR, Spring Only, Blossom, Free', 0, 0, 'Nanshan Road, south of West Lake, Xihu District', null, 60, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
insert into public.places (slug, name_zh, name_en, city, district_id, category, description, tags, price_min, price_max, address, metro, duration_minutes, source, country)
  values ('manjuelong-osmanthus-valley', '满觉陇', 'Manjuelong Osmanthus Valley', 'hangzhou', 'xihu', 'activity', 'A valley of osmanthus trees behind the lake that the whole city smells for about three weeks each autumn. Teahouses put tables out under the trees and you sit in the falling flowers. Late September to October only, and genuinely one of the best things in Hangzhou in that window.', 'Park, WORTH A DETOUR, Autumn Only, Osmanthus, Teahouses', 0, 0, 'Manjuelong Road, south of West Lake, Xihu District', null, 120, 'hangzhou-fun-guide.html', 'CN')
  on conflict (slug) do update set name_zh = excluded.name_zh, name_en = excluded.name_en, city = excluded.city, district_id = excluded.district_id, category = excluded.category, description = excluded.description, tags = excluded.tags, price_min = excluded.price_min, price_max = excluded.price_max, address = excluded.address, metro = excluded.metro, duration_minutes = excluded.duration_minutes, source = excluded.source, country = excluded.country;
