  values ('wukang-mansion', '武康大楼', 'Wukang Mansion', 'shanghai', 'xuhui', 'sight', 'The flatiron shaped 1924 building at the fork of Wukang Road. The photo everyone takes, then coffee on Anfu Road.', 'Landmark, PHOTO SPOT, Golden hour, Pair with Anfu Rd cafes', 0, 0, '1850 Huaihai Middle Rd', 'Wukang Rd (Line 11)', null, 'itinerary.html', 'CN')
